    node.entries[k].key = cbor("max_validity_ms")
    node.entries[k].value = cbor(uint64(x.max_validity_ms.get))
    inc k
  node.entries[k].key = cbor("scopes")
  let a32 = newCborArray(x.scopes.len)
  node.entries[k].value = a32
  for i33 in 0 ..< x.scopes.len:
