proc stepEncLcnApTarget*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnApTarget](src)
  case x.kind
  of LcnApTargetKind.Issued:
    dst[] = cbor("issued")
  of LcnApTargetKind.Self:
    dst[] = cbor("self")
  of LcnApTargetKind.lcn_Ap_subject:
    w.later(stepEncLcnApSubject, addr x.arm_lcn_Ap_subject, addr dst[])

proc stepDecLcnApTarget*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnApTarget](dst)
  case generatedSchema().arm("lcn.ap_target#", v)
  of 0:
    r[] = LcnApTarget(kind: LcnApTargetKind.lcn_Ap_subject)
    w.later(stepDecLcnApSubject, v, addr r.arm_lcn_Ap_subject)
  of 1:
    r[] = LcnApTarget(kind: LcnApTargetKind.Self)
  of 2:
    r[] = LcnApTarget(kind: LcnApTargetKind.Issued)
  else:
    raiseAssert "a checked value selects a known arm"

